<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->prepare('SELECT c.*,v.verification_code FROM certificates c JOIN students s ON s.id=c.student_id LEFT JOIN certificate_verifications v ON v.certificate_id=c.id WHERE s.user_id=? ORDER BY c.id DESC');$q->execute([actor_id()]);page_top('Digital Certificates');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Certificate</th><th>Number</th><th>Issue Date</th><th>Status</th><th>Verification</th></tr><?php foreach($q as $c):?><tr><td><?=e($c['type'])?></td><td><?=e($c['certificate_no'])?></td><td><?=e($c['issue_date'])?></td><td><?=e($c['status'])?></td><td><?php if($c['verification_code']):?><a target='_blank' href='../public/verification.php?code=<?=urlencode($c['verification_code'])?>'>Verify</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php page_bottom();
